import { computed, effect, Injectable, signal } from '@angular/core';
import { TmdbMovie, WatchItem } from './movie';

@Injectable({ providedIn: 'root' })
export class WatchlistStore {
    private readonly KEY = 'watchlist';

    private _items = signal<WatchItem[]>(
        this.parse(localStorage.getItem(this.KEY))
    );

    // Unwatched movies first, preserving relative insertion order within
    // each group (a stable partition; Array.prototype.sort is stable).
    items = computed<readonly WatchItem[]>(() =>
        [...this._items()].sort((a, b) => Number(a.watched) - Number(b.watched))
    );
    count = computed(() => this._items().length);
    watchedCount = computed(() => this._items().filter(m => m.watched).length);

    constructor() {
        effect(() => {
            localStorage.setItem(this.KEY, JSON.stringify(this._items()));
        });
    }

    private parse(raw: string | null): WatchItem[] {
        try {
            const parsed = JSON.parse(raw ?? '[]');
            return Array.isArray(parsed) ? parsed : [];
        } catch {
            return [];
        }
    }

    private partition(items: WatchItem[]): WatchItem[] {
        const copy = [...items];
        copy.sort((a, b) => Number(a.watched) - Number(b.watched));
        return copy;
    }

    add(movie: TmdbMovie) {
        this._items.update(items =>
            items.some(m => m.id === movie.id)
                ? items
                : this.partition([...items, {
                    id: movie.id,
                    title: movie.title,
                    poster_path: movie.poster_path,
                    release_date: movie.release_date,
                    watched: false
                }])
        );
    }

    remove(id: number) {
        this._items.update(items => this.partition(items.filter(m => m.id !== id)));
    }

    toggleWatched(id: number) {
        const current = this._items();
        const matching = current.find(it => it.id === id);
        if (!matching) {
            return;
        }
        const updated = current.map(it =>
            it.id === id ? { ...it, watched: !it.watched } : it
        );
        this._items.set(
            updated.filter(i => !i.watched).concat(updated.filter(i => i.watched))
        );
    }
}

import { TestBed } from '@angular/core/testing';
import { WatchlistStore } from './watchlist-store';
import { TmdbMovie } from './movie';

describe('WatchlistStore', () => {
  let service: WatchlistStore;

  const movie = (id: number, title: string): TmdbMovie => ({
    id,
    title,
    release_date: '2024-01-01',
    poster_path: null,
    overview: '',
  });

  beforeEach(() => {
    localStorage.removeItem('watchlist');
    TestBed.configureTestingModule({});
    service = TestBed.inject(WatchlistStore);
  });

  it('should be created', () => {
    expect(service).toBeTruthy();
  });

  it('should toggle watched from false to true and back', () => {
    service.add(movie(1, 'A'));
    expect(service.items().find(m => m.id === 1)!.watched).toBe(false);

    service.toggleWatched(1);
    let item = service.items().find(m => m.id === 1);
    expect(item).toBeDefined();
    expect(item!.watched).toBe(true);

    service.toggleWatched(1);
    item = service.items().find(m => m.id === 1);
    expect(item!.watched).toBe(false);
  });

  it('should only toggle the item with the matching id', () => {
    service.add(movie(1, 'A'));
    service.add(movie(2, 'B'));

    service.toggleWatched(1);

    const items = service.items();
    expect(items.find(m => m.id === 1)!.watched).toBe(true);
    expect(items.find(m => m.id === 2)!.watched).toBe(false);
  });

  it('should list unwatched items before watched ones, stable within each group', () => {
    service.add(movie(1, 'A'));
    service.add(movie(2, 'B'));
    service.add(movie(3, 'C'));

    service.toggleWatched(2);

    expect(service.items().map(m => m.id)).toEqual([1, 3, 2]);

    service.remove(3);
    expect(service.items().map(m => m.id)).toEqual([1, 2]);

    service.toggleWatched(1);
    expect(service.items().map(m => m.id)).toEqual([2, 1]);
  });

  it('should keep stable ordering when toggling multiple items', () => {
    service.add(movie(1, 'A'));
    service.add(movie(2, 'B'));
    service.add(movie(3, 'C'));

    service.toggleWatched(1);
    service.toggleWatched(3);

    expect(service.items().map(m => m.id)).toEqual([2, 1, 3]);
  });

  it('should expose counts reflecting watched state', () => {
    service.add(movie(1, 'A'));
    service.add(movie(2, 'B'));
    expect(service.count()).toBe(2);
    expect(service.watchedCount()).toBe(0);

    service.toggleWatched(1);
    expect(service.watchedCount()).toBe(1);
  });
});

